import { BadRequestException, ForbiddenException, Injectable, OnModuleDestroy, OnModuleInit } from "@nestjs/common";
import type { AccountingHealth, Anomaly, BillingSchedule, CashflowPoint, CashflowReport, ClientFinanceSummary, CopilotAnswer, FinanceDashboard, FinanceKpi, FinanceMetric, Invoice, JournalEntry, JournalLine, Payable, Payment, PaymentAllocation, PaymentPromise, ProfitabilityRow, ProjectFinanceSummary } from "@zyteron/contracts";
import { can, canSeeMargins } from "./finance.access.js";
