  /** Convierte una propuesta en BORRADOR (requiere journal.create); la contabilización es otra acción humana. */
  async draftFromProposal(body:Row,actor:FinanceActor){this.ctx.require(actor,"journal.create");const lines=Array.isArray(body.lines)?body.lines.map((l:Row)=>({accountCode:String(l.accountCode),debit:Number(l.debit)||0,credit:Number(l.credit)||0})):[];return this.ledger.createEntry({entryDate:body.entryDate??todayCl(),description:String(body.description??"Propuesta Contador Zyteron"),lines},actor,{sourceType:"COPILOT_PROPOSAL",sourceId:optionalId(body.analysisRunId)});}
